// =============================================================================
//  LocalizationID.cpp    The Hell 4 -- Indonesian (Bahasa Indonesia) overlay
//  LANG_ID = 2. Latin/ASCII: plain C literals, no CP1251 escapes, no special font
//  handling. This file owns ONLY the Indonesian tables + the two registry getters.
//  Keys byte-exactly match the English source literal (case/punct sensitive).
//  Untranslated keys fall back to English automatically. English source & the
//  Russian tables are never touched here.
// =============================================================================

