const UiStr* ID_GetStrTable( int ovlId, int* n )
{
	switch( ovlId ){
		case OVL_UI: *n = (int)(sizeof(ID_Ui)/sizeof(ID_Ui[0])); return ID_Ui;
		case OVL_MENU: *n = (int)(sizeof(ID_Menu)/sizeof(ID_Menu[0])); return ID_Menu;
		case OVL_UNIQUE_ITEM: *n = (int)(sizeof(ID_UniqueItem)/sizeof(ID_UniqueItem[0])); return ID_UniqueItem;
		case OVL_AFFIX_PREFIX: *n = (int)(sizeof(ID_AffixPrefix)/sizeof(ID_AffixPrefix[0])); return ID_AffixPrefix;
		case OVL_AFFIX_SUFFIX: *n = (int)(sizeof(ID_AffixSuffix)/sizeof(ID_AffixSuffix[0])); return ID_AffixSuffix;
		case OVL_BASE_ITEM: *n = (int)(sizeof(ID_BaseItem)/sizeof(ID_BaseItem[0])); return ID_BaseItem;
		case OVL_BASE_NAME2: *n = (int)(sizeof(ID_BaseName2)/sizeof(ID_BaseName2[0])); return ID_BaseName2;
		case OVL_ICEAGE: *n = (int)(sizeof(ID_IceAge)/sizeof(ID_IceAge[0])); return ID_IceAge;
		case OVL_ELEMENT: *n = (int)(sizeof(ID_Element)/sizeof(ID_Element[0])); return ID_Element;
		case OVL_SPICIES: *n = (int)(sizeof(ID_Spicies)/sizeof(ID_Spicies[0])); return ID_Spicies;
		case OVL_SPELL: *n = (int)(sizeof(ID_Spell)/sizeof(ID_Spell[0])); return ID_Spell;
		case OVL_SPELL_NOM: *n = (int)(sizeof(ID_SpellNom)/sizeof(ID_SpellNom[0])); return ID_SpellNom;
		case OVL_PERK_NAME: *n = (int)(sizeof(ID_PerkName)/sizeof(ID_PerkName[0])); return ID_PerkName;
		case OVL_PERK_DESC: *n = (int)(sizeof(ID_PerkDesc)/sizeof(ID_PerkDesc[0])); return ID_PerkDesc;
		case OVL_WARP: *n = (int)(sizeof(ID_Warp)/sizeof(ID_Warp[0])); return ID_Warp;
	}
	*n = 0; return 0;
}

const IdxStr* ID_GetIdxTable( int ovlId, int* n )
{
	switch( ovlId ){
		case OVL_SPEECH: *n = (int)(sizeof(ID_Speech)/sizeof(ID_Speech[0])); return ID_Speech;
		case OVL_ONSCREEN: *n = (int)(sizeof(ID_OnScreen)/sizeof(ID_OnScreen[0])); return ID_OnScreen;
		case OVL_QUEST: *n = (int)(sizeof(ID_Quest)/sizeof(ID_Quest[0])); return ID_Quest;
	}
	*n = 0; return 0;
}


